from itertools import combinations
# Build board nodes
nodes=[]
for r in range(3):
    for c in range(3): nodes.append(('u',r,c,37+6*c,20+6*r))
for r in range(4):
    for c in range(5): nodes.append(('l',r,c,31+6*c,38+6*r))
idx={n[:3]:i for i,n in enumerate(nodes)}
edges={i:set() for i in range(len(nodes))}
for i,a in enumerate(nodes):
    for j,b in enumerate(nodes):
        if a[0]==b[0] and ((a[1]==b[1] and abs(a[2]-b[2])==2) or (a[2]==b[2] and abs(a[1]-b[1])==2)):
            edges[i].add(j); edges[j].add(i)
        elif a[0]!=b[0] and a[3]==b[3] and abs(a[4]-b[4])==12:
            edges[i].add(j); edges[j].add(i)
start=tuple(sorted([idx[('u',1,1)],idx[('u',2,0)],idx[('u',2,1)],idx[('l',1,3)]]))
goals=[]
for r in range(4):
    for c0 in range(2): goals.append(tuple(sorted(idx[('l',r,c)] for c in range(c0,c0+4))))
print(start,goals)
from collections import deque
q=deque([start]); prev={start:None}; pm={}
goal=None
while q:
 s=q.popleft()
 if s in goals: goal=s; break
 for k,p in enumerate(s):
  for t in edges[p]:
   if t in s: continue
   ns=list(s); ns[k]=t; ns=tuple(sorted(ns))
   if ns not in prev:
    prev[ns]=s; pm[ns]=(p,t); q.append(ns)
print('dist',end=' ')
path=[]
while goal!=start:
 path.append(pm[goal]); goal=prev[goal]
path=path[::-1]
print(len(path))
for p,t in path: print(nodes[p],'=>',nodes[t], 'click', (nodes[p][3],nodes[p][4]),(nodes[t][3],nodes[t][4]))

